import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const s=JSON.parse('{"title":"组件添加界面深度解析","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/组件添加界面深度解析.md","filePath":"脚本系统/专题研究/组件添加界面深度解析.md","lastUpdated":1776864657000}'),h={name:"脚本系统/专题研究/组件添加界面深度解析.md"};function d(o,l,c,n,t,_){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="组件添加界面深度解析" tabindex="-1">组件添加界面深度解析 <a class="header-anchor" href="#组件添加界面深度解析" aria-label="Permalink to “组件添加界面深度解析”">​</a></h1><p>本文件基于 <code>资料/基础写脚本界面截图/</code> 中的组件添加界面截图整理，目标是把“素材/物体可添加哪些组件、这些组件按什么类别组织”整理成更细的知识文档。</p><blockquote><p>说明：内容基于截图 OCR 与人工纠错，名称个别处仍可能存在识别误差，后续可继续校对。</p></blockquote><h2 id="_1-组件分类总览" tabindex="-1">1. 组件分类总览 <a class="header-anchor" href="#_1-组件分类总览" aria-label="Permalink to “1. 组件分类总览”">​</a></h2><p>从多张“添加组件”截图可以确认，组件添加面板至少按以下分类组织：</p><ul><li>通用</li><li>战斗</li><li>装置</li><li>显示</li><li>交互</li><li>自定义</li></ul><p>这说明创游世界并不是把全部组件扔在一个平面列表里，而是采用“按子系统分类”的方式组织能力。这样的设计有几个直接好处：</p><ul><li>方便创作者按目标快速定位能力</li><li>让不同类型素材的功能边界更清晰</li><li>有利于后续扩展新组件，而不至于界面完全失控</li></ul><h2 id="_2-已识别的装置类组件" tabindex="-1">2. 已识别的装置类组件 <a class="header-anchor" href="#_2-已识别的装置类组件" aria-label="Permalink to “2. 已识别的装置类组件”">​</a></h2><p>根据 <code>Screenshot_20260417_215321.jpg</code> 等截图，装置相关区域至少可识别：</p><ul><li>物理</li><li>可互动</li><li>开关</li><li>物体检测器</li><li>阻挡通行</li><li>等级</li><li>告示牌</li><li>物体 UI</li><li>地刺</li><li>怪物门</li><li>传送门</li><li>弹簧</li><li>不稳定平台</li><li>传送带（OCR 有误写作“传迷带”）</li><li>梯子</li><li>机关组件（OCR 疑似“机关检组件”）</li><li>旋转</li><li>往返移动</li></ul><h3 id="结构理解" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解" aria-label="Permalink to “结构理解”">​</a></h3><p>装置类组件明显偏向“场景机关”和“玩法交互装置”，大致可以再细分为：</p><h4 id="_2-1-基础物理-交互控制" tabindex="-1">2.1 基础物理/交互控制 <a class="header-anchor" href="#_2-1-基础物理-交互控制" aria-label="Permalink to “2.1 基础物理/交互控制”">​</a></h4><ul><li>物理</li><li>可互动</li><li>开关</li><li>阻挡通行</li><li>物体检测器</li></ul><p>这部分更像是“让一个物体成为可参与游戏规则的对象”的基础层。</p><h4 id="_2-2-场景机关类" tabindex="-1">2.2 场景机关类 <a class="header-anchor" href="#_2-2-场景机关类" aria-label="Permalink to “2.2 场景机关类”">​</a></h4><ul><li>地刺</li><li>怪物门</li><li>传送门</li><li>弹簧</li><li>不稳定平台</li><li>传送带</li><li>梯子</li><li>旋转</li><li>往返移动</li></ul><p>这类组件说明创游内置了大量关卡设计常见机关，创作者不一定需要完全手搓逻辑。</p><h4 id="_2-3-信息与表现辅助" tabindex="-1">2.3 信息与表现辅助 <a class="header-anchor" href="#_2-3-信息与表现辅助" aria-label="Permalink to “2.3 信息与表现辅助”">​</a></h4><ul><li>告示牌</li><li>物体 UI</li><li>等级</li></ul><p>这部分说明装置不只是“碰撞物”，也可以承担提示、状态展示和成长配置等职责。</p><h2 id="_3-已识别的战斗类组件" tabindex="-1">3. 已识别的战斗类组件 <a class="header-anchor" href="#_3-已识别的战斗类组件" aria-label="Permalink to “3. 已识别的战斗类组件”">​</a></h2><p>根据 <code>Screenshot_20260417_215325.jpg</code>，战斗类组件至少可识别：</p><ul><li>生命</li><li>伤害</li><li>武器槽</li></ul><h3 id="结构理解-1" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解-1" aria-label="Permalink to “结构理解”">​</a></h3><p>战斗类组件是“战斗能力挂载”的核心入口：</p><ul><li><code>生命</code> 决定能否承受伤害、是否可摧毁、是否会死亡</li><li><code>伤害</code> 决定该物体能对其他目标造成什么攻击结果</li><li><code>武器槽</code> 则说明对象可以装备或管理武器</li></ul><p>这三者组合起来，已经足以让一个角色/装置/特殊物体具备基础战斗交互能力。</p><h2 id="_4-已识别的显示类组件" tabindex="-1">4. 已识别的显示类组件 <a class="header-anchor" href="#_4-已识别的显示类组件" aria-label="Permalink to “4. 已识别的显示类组件”">​</a></h2><p>根据 <code>Screenshot_20260417_215328.jpg</code>，显示类组件至少可识别：</p><ul><li>卷轴循环</li><li>图片分身</li><li>九宫切图</li><li>描边</li><li>拖尾</li><li>粒子特效</li></ul><h3 id="结构理解-2" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解-2" aria-label="Permalink to “结构理解”">​</a></h3><p>显示类组件偏向“视觉表现层”，可粗分为：</p><h4 id="_4-1-贴图与布局表现" tabindex="-1">4.1 贴图与布局表现 <a class="header-anchor" href="#_4-1-贴图与布局表现" aria-label="Permalink to “4.1 贴图与布局表现”">​</a></h4><ul><li>九宫切图</li><li>图片分身</li><li>卷轴循环</li></ul><p>这说明创游不只是给你一张静态图，而是支持一定程度的 UI/场景贴图高级表现。</p><h4 id="_4-2-特效增强" tabindex="-1">4.2 特效增强 <a class="header-anchor" href="#_4-2-特效增强" aria-label="Permalink to “4.2 特效增强”">​</a></h4><ul><li>描边</li><li>拖尾</li><li>粒子特效</li></ul><p>这类组件用于提高视觉辨识度与打击感，也能减少完全依赖脚本实现特效的成本。</p><h2 id="_5-已识别的交互类组件" tabindex="-1">5. 已识别的交互类组件 <a class="header-anchor" href="#_5-已识别的交互类组件" aria-label="Permalink to “5. 已识别的交互类组件”">​</a></h2><p>根据 <code>Screenshot_20260417_215329.jpg</code>，交互类组件至少可识别：</p><ul><li>触摸模板（OCR 近似“触模板”）</li><li>按钮（OCR 误成“投钮”）</li><li>拖拽</li></ul><h3 id="结构理解-3" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解-3" aria-label="Permalink to “结构理解”">​</a></h3><p>交互类组件很可能承担输入层职责，尤其与 UI/可点击对象有关：</p><ul><li><code>按钮</code>：典型点击交互入口</li><li><code>拖拽</code>：可实现拖动式交互</li><li><code>触摸模板</code>：可能是更通用的触摸/命中响应模板</li></ul><p>如果结合 UI 系统来理解，这一类组件很可能是“把静态显示对象变成可操作界面元素”的关键。</p><h2 id="_6-自定义组件入口的意义" tabindex="-1">6. 自定义组件入口的意义 <a class="header-anchor" href="#_6-自定义组件入口的意义" aria-label="Permalink to “6. 自定义组件入口的意义”">​</a></h2><p>根据 <code>Screenshot_20260417_215330.jpg</code>，在添加组件界面中可直接看到：</p><ul><li><code>+自定义组件</code></li></ul><p>这很重要，因为它说明自定义组件并不是只能在某个深层编辑器里使用，而是已经被正式纳入“组件体系”。</p><h3 id="这代表什么" tabindex="-1">这代表什么？ <a class="header-anchor" href="#这代表什么" aria-label="Permalink to “这代表什么？”">​</a></h3><ul><li>自定义组件与内置组件在使用层面是并列关系</li><li>创作者可以把自己封装的能力像官方组件一样挂到物体上</li><li>自定义组件实际上承担了“用户扩展系统”的角色</li></ul><p>换句话说，自定义组件不是外挂补丁，而是创游组件化设计中的正规扩展位。</p><h2 id="_7-关于素材类型与组件边界的推断" tabindex="-1">7. 关于素材类型与组件边界的推断 <a class="header-anchor" href="#_7-关于素材类型与组件边界的推断" aria-label="Permalink to “7. 关于素材类型与组件边界的推断”">​</a></h2><p>结合教程文档“素材不是物体”“不同类型的素材可添加组件不同”等内容，可以推断：</p><ul><li>组件能力和素材类型存在绑定关系</li><li>某些组件只能挂在特定类型素材上</li><li>组件面板展示内容会随当前对象/素材类型而变化</li></ul><p>例如：</p><ul><li>地块组件只能挂在地块素材上</li><li>道具组件只能挂在道具素材上</li><li>战斗、显示、交互、装置等组件则可能对不同素材开放程度不同</li></ul><p>这意味着创游的组件系统并不是完全自由拼装，而是“有约束的可组合”。</p><h2 id="_8-对创作者的实际启发" tabindex="-1">8. 对创作者的实际启发 <a class="header-anchor" href="#_8-对创作者的实际启发" aria-label="Permalink to “8. 对创作者的实际启发”">​</a></h2><h3 id="_8-1-做功能时先想-组件化" tabindex="-1">8.1 做功能时先想“组件化” <a class="header-anchor" href="#_8-1-做功能时先想-组件化" aria-label="Permalink to “8.1 做功能时先想“组件化””">​</a></h3><p>如果一个能力已经有现成组件，就优先挂组件，而不是先写脚本硬造。</p><h3 id="_8-2-做关卡机关时优先看装置类" tabindex="-1">8.2 做关卡机关时优先看装置类 <a class="header-anchor" href="#_8-2-做关卡机关时优先看装置类" aria-label="Permalink to “8.2 做关卡机关时优先看装置类”">​</a></h3><p>装置类已经覆盖大量经典关卡机关，适合做平台跳跃、解谜、陷阱等设计。</p><h3 id="_8-3-做视觉效果时优先看显示类" tabindex="-1">8.3 做视觉效果时优先看显示类 <a class="header-anchor" href="#_8-3-做视觉效果时优先看显示类" aria-label="Permalink to “8.3 做视觉效果时优先看显示类”">​</a></h3><p>很多常见表现完全可以通过显示类组件解决，而不是全部依赖事件脚本。</p><h3 id="_8-4-做复用功能时使用自定义组件" tabindex="-1">8.4 做复用功能时使用自定义组件 <a class="header-anchor" href="#_8-4-做复用功能时使用自定义组件" aria-label="Permalink to “8.4 做复用功能时使用自定义组件”">​</a></h3><p>如果一个功能需要反复挂在多个物体上，自定义组件比复制脚本更规范、更容易维护。</p><h2 id="_9-关键词" tabindex="-1">9. 关键词 <a class="header-anchor" href="#_9-关键词" aria-label="Permalink to “9. 关键词”">​</a></h2><ul><li>添加组件</li><li>通用</li><li>战斗</li><li>装置</li><li>显示</li><li>交互</li><li>自定义</li><li>地刺</li><li>传送门</li><li>弹簧</li><li>梯子</li><li>卷轴循环</li><li>九宫切图</li><li>粒子特效</li><li>按钮</li><li>拖拽</li><li>自定义组件</li></ul>',71)])])}const b=i(h,[["render",d]]);export{s as __pageData,b as default};
